-- =============================================================================================
-- Gate G1 (docs/specs/analytics-v2.md §8.1): BigQuery objects for analytics v2, ready to paste.
-- Generated by `npm run analytics` from g1_checklist.sql, g1_fixture_check.template.sql and the
-- six object files; metricsSql.test.ts fails if it is stale. Do not edit apply-g1.sql itself.
--
-- PART A (below the checklist) builds a scratch copy of the views over fixture rows and checks
-- what they return. PART B creates, in order:
--   deleted_users, deleted_devices   two key-only tables (written by erasure, AN-04)
--   events_people_all                all the logic; founders only (has user_info)
--   events_clean_all                 the same without user_info, both environments
--   events_clean                     what the Metrics queries read (production only)
--   events_people                    founders only, production only
-- Neither part changes or deletes a row of `onquest_analytics.events`; only step 2 does.
--
-- Known from the CTO's console (26 Nov 2026): `properties`, `set`, `set_once` and
-- `person_properties` are JSON; `ip` was filled on 162 rows; Preview has had
-- NEXT_PUBLIC_POSTHOG_KEY since 25 Nov, so rows without `env` include Preview traffic.
-- The views read only uuid, event, distinct_id, timestamp, properties and site_url.
--
-- DRY-RUN CHECKLIST (bq CLI or the console, signed in as a founder, default project = the
-- analytics project). Report the results marked (report) on the AN-01 PR.
--
-- [ ] 1. Schema unchanged since the console check (report if not):
--          bq show --schema --format=prettyjson onquest_analytics.events
--
-- [ ] 2. Raw IP (report the counts before and after):
--          SELECT COUNTIF(ip IS NOT NULL AND ip != '') AS rows_with_ip,
--                 COUNTIF(JSON_VALUE(properties, '$."$ip"') IS NOT NULL) AS rows_with_dollar_ip
--          FROM `onquest_analytics.events`;
--        Then null the column once (spec §8.1; wait and retry if it reports a streaming buffer):
--          UPDATE `onquest_analytics.events` SET ip = NULL WHERE ip IS NOT NULL;
--        `$ip` inside properties is never read by the views (allowlist); founders and the
--        analytics-eraser account still see it in the raw table.
--
-- [ ] 3. Which PostHog `$` keys exist in history (report the list):
--          SELECT key, COUNT(*) AS rows_with_key
--          FROM `onquest_analytics.events`, UNNEST(JSON_KEYS(properties, 1)) AS key
--          WHERE STARTS_WITH(key, '$')
--          GROUP BY key ORDER BY key;
--        Only $current_url and $pathname pass into the views; everything else ($geoip_*,
--        $set, $set_once, $ip, lat/long, postcode, …) is left out by the properties allowlist.
--
-- [ ] 4. Rows without properties (expect 0; they would count as production):
--          SELECT COUNTIF(properties IS NULL) AS rows_without_properties
--          FROM `onquest_analytics.events`;
--
-- [ ] 5. Where rows without `env` come from (report). The views take their env from the first
--        of $current_url, $host, site_url whose host is ours (onquest.in / www.onquest.in →
--        production; *.vercel.app or localhost → preview); otherwise production. The v1 client
--        sends a URL only on $pageview and hard-codes it to https://onquest.in, so v1 Preview
--        rows can't be told apart by URL; this shows what site_url and app_version can tell:
--          SELECT LOWER(NET.HOST(JSON_VALUE(properties, '$."$current_url"'))) AS url_host,
--                 LOWER(NET.HOST(site_url)) AS site_host,
--                 JSON_VALUE(properties, '$.app_version') AS app_version,
--                 COUNT(*) AS events, MIN(`timestamp`) AS first_seen, MAX(`timestamp`) AS last_seen
--          FROM `onquest_analytics.events`
--          WHERE JSON_VALUE(properties, '$.env') IS NULL
--          GROUP BY 1, 2, 3 ORDER BY events DESC;
--
-- [ ] 6. PART A: paste from the PART A line to the PART B line and Run (or from the CLI:
--          bq query --use_legacy_sql=false < docs/analytics/bigquery/g1_fixture_check.sql ).
--        Expect the "failing_check" result to be empty and the script to finish; it drops the
--        scratch dataset. A failure stops at the ASSERT: report the failing checks and stop.
--
-- [ ] 7. PART B: dry-run, then apply, one object at a time and in order (each view reads the
--        one before it, so its dry run passes only once the previous one exists):
--          cd docs/analytics/bigquery
--          for f in deleted_users deleted_devices events_people_all events_clean_all \
--                   events_clean events_people; do
--            bq query --use_legacy_sql=false --dry_run < "$f.sql" && \
--            bq query --use_legacy_sql=false < "$f.sql" || break
--          done
--        Or paste from the PART B line to the end into the console and Run it (one script).
--
-- [ ] 8. Dry-run every Metrics query (docs/analytics/v2/metrics.csv, column "BigQuery SQL",
--        18 queries) with `bq query --use_legacy_sql=false --dry_run '<query>'`. All must pass.
--
-- [ ] 9. Sanity checks on history (run for real; small):
--        a. No v1-only name is left (expect no rows; 'blog_managed' only for an unknown action):
--             SELECT name, COUNT(*) FROM `onquest_analytics.events_clean_all`
--             WHERE name IN ('create_option_tapped', 'blog_managed', 'blog_deleted', 'blog_liked',
--               'blog_comment_posted', 'blog_quest_linked', 'blog_previewed', 'blog_quest_opened')
--             GROUP BY name;
--        b. "Blog adoption" and "Blog read-through" (metrics.csv) return non-zero numbers over
--           history (AC8).
--        c. Nothing but $-events, bots and duplicates is lost (expect equal numbers):
--             SELECT (SELECT COUNT(DISTINCT COALESCE(JSON_VALUE(properties, '$.event_id'), uuid))
--                     FROM `onquest_analytics.events`
--                     WHERE NOT STARTS_WITH(event, '$') OR event = '$pageview') AS raw_events,
--                    (SELECT COUNT(*) FROM `onquest_analytics.events_clean_all`) AS view_events;
--        d. No location, IP or email in the clean views (expect 0 and 0):
--             SELECT
--               (SELECT COUNT(*) FROM `onquest_analytics.events_clean_all`,
--                  UNNEST(JSON_KEYS(properties, 1)) AS key
--                WHERE STARTS_WITH(key, '$') AND key NOT IN ('$current_url', '$pathname'))
--                 AS other_dollar_keys,
--               (SELECT COUNT(*) FROM `onquest_analytics.events_clean_all` AS clean
--                WHERE REGEXP_CONTAINS(TO_JSON_STRING(clean), r'[^\s@"]+@[^\s@"]+\.[a-z]'))
--                 AS email_shaped;
--
-- [ ] 10. Access. events_people, events_people_all and the raw `events` table hold emails once
--         user_info is on: keep them founders only. If anyone else needs events_clean, give it
--         to them as an authorized view in another dataset, not as access to this dataset.
--
-- [ ] 11. Comment "G1 passed" on the AN-01 PR with the (report) results.
--
-- Later, not blocking the merge (spec §8.1): once Preview has v2 data with the oq_actx cookie
-- off (after AN-07 is on Preview), run on events_clean_all with WHERE env = 'preview':
--   - the Metrics "Viewer → creator" query (FROM events_clean_all, plus AND env = 'preview' in
--     both CTEs), and
--   - SELECT COUNTIF(JSON_VALUE(properties, '$.first_seen_ts') IS NOT NULL) AS with_first_seen,
--            COUNT(*) AS sign_ups
--     FROM `onquest_analytics.events_clean_all` WHERE env = 'preview' AND name = 'user_signed_up';
-- and confirm both are non-zero.
-- =============================================================================================

-- =============================================================================================
-- PART A: fixture check. Paste from here to the PART B line and Run. It touches only the
-- scratch dataset onquest_analytics_g1_check, never onquest_analytics.
-- =============================================================================================
-- Generated by `npm run analytics` from g1_fixture_check.template.sql and the view files.
-- Do not edit: change those and run the script again.
-- G1 Part A: fixture check (docs/specs/analytics-v2.md §8.1, review round 1 should-fix 5).
-- Runs the real events_people_all / events_clean_all SQL over literal rows in a scratch dataset
-- and checks the result: v1 renames and values, v1 identity, the env fallback, the properties
-- allowlist, the shared-device guard, account_deleted, the anon_id fill, person_id and the derived
-- properties. Touches only the scratch dataset onquest_analytics_g1_check, and drops it on
-- success. On failure it lists the failing checks and the ASSERT stops the script; drop the
-- scratch dataset by hand afterwards.
--
-- Devices: D1 is shared by user-a (deleted) and user-b; D2 is user-c's; D3 a signed-out
-- Preview visitor; D4 user-p's, on Preview.

CREATE SCHEMA IF NOT EXISTS `onquest_analytics_g1_check`
OPTIONS (description = 'Scratch for the analytics v2 G1 fixture check; safe to drop');

CREATE OR REPLACE TABLE `onquest_analytics_g1_check.events` (
  uuid STRING,
  event STRING,
  distinct_id STRING,
  `timestamp` TIMESTAMP,
  properties JSON,
  site_url STRING,
  ip STRING
);

