kept AS (
  SELECT candidate.*
  FROM common AS candidate
  LEFT JOIN (SELECT DISTINCT user_id FROM `onquest_analytics_g1_check.deleted_users`) AS deleted_user
    ON deleted_user.user_id = candidate.user_id
  LEFT JOIN (SELECT DISTINCT anon_id, user_id FROM `onquest_analytics_g1_check.deleted_devices`) AS deleted_device
    ON deleted_device.anon_id = candidate.anon_id
    -- Shared-device guard (same as the erasure DELETE): only signed-out rows or the deleted
    -- person's own rows. Another person's signed-in rows on that device stay.
    AND (candidate.user_id IS NULL OR candidate.user_id = deleted_device.user_id)
  WHERE candidate.name = 'account_deleted'
    OR (deleted_user.user_id IS NULL AND deleted_device.anon_id IS NULL)
),

filled AS (
  SELECT
    * EXCEPT (anon_id, browser_anon_id),
    COALESCE(
      anon_id,
      IF(
        user_id IS NULL OR name IN ('notification_sent', 'account_deleted'),
        NULL,
        COALESCE(
          LAST_VALUE(browser_anon_id IGNORE NULLS) OVER user_until_now,
          FIRST_VALUE(browser_anon_id IGNORE NULLS) OVER user_from_now
        )
      )
    ) AS anon_id
  FROM (SELECT *, IF(type != 'server', anon_id, NULL) AS browser_anon_id FROM kept)
  WINDOW
    user_until_now AS (
      PARTITION BY user_id ORDER BY ts, event_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ),
    user_from_now AS (
      PARTITION BY user_id ORDER BY ts, event_id ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING
    )
)

SELECT
  event_id,
  name,
  type,
  env,
  ts,
  COALESCE(sent_client_ts, IF(raw_env IS NULL AND type != 'server', exported_ts, NULL)) AS client_ts,
  user_id,
  anon_id,
  session_id,
  platform,
  os,
  browser,
  screen,
  country,
  app_version,
  CASE
    WHEN name = 'user_signed_up' AND anon_id IS NOT NULL THEN
      JSON_SET(properties, '$.first_seen_ts', MIN(ts) OVER (PARTITION BY anon_id))
    WHEN name = 'user_signed_in' THEN
      JSON_SET(properties, '$.days_since_last_sign_in', TIMESTAMP_DIFF(ts, LAG(ts) OVER sign_ins, DAY))
    ELSE properties
  END AS properties,
  -- DAU: the user, else the user last seen on this device (over all time, so a past day's count
  -- can change when a device later signs in to another account), else the device.
  COALESCE(
    user_id,
    IF(anon_id IS NULL, NULL, LAST_VALUE(user_id IGNORE NULLS) OVER device),
    anon_id
  ) AS person_id,
  user_info
FROM filled
WINDOW
  sign_ins AS (PARTITION BY user_id, name IN ('user_signed_up', 'user_signed_in') ORDER BY ts),
  device AS (PARTITION BY anon_id ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING);

-- ---- events_clean_all.sql, reading the fixture tables ----
-- events_clean_all: events_people_all without user_info (no email, username or city), both
-- environments. For Preview checks: add WHERE env = 'preview'. docs/specs/analytics-v2.md §5.3.
CREATE OR REPLACE VIEW `onquest_analytics_g1_check.events_clean_all`
OPTIONS (
  description = 'v2 events without user_info, all environments (analytics-v2 spec 5.3). Add WHERE env = preview for Preview checks.'
)
AS
SELECT * EXCEPT (user_info)
FROM `onquest_analytics_g1_check.events_people_all`;

CREATE TEMP TABLE fixture_checks AS
SELECT * FROM UNNEST([
  STRUCT('27 rows survive: duplicate, $identify, bot, deleted user and device dropped' AS check_name, IFNULL((SELECT COUNT(*) FROM `onquest_analytics_g1_check.events_people_all`) = 27, FALSE) AS ok),
  STRUCT('e07 to e10 dropped' AS check_name, IFNULL((SELECT COUNT(*) FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id IN ('e07', 'e08', 'e09', 'e10')) = 0, FALSE) AS ok),
  STRUCT('e01 kept once (duplicate event_id)' AS check_name, IFNULL((SELECT COUNT(*) FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e01') = 1, FALSE) AS ok),
  STRUCT('e01 v1 signed-out blog_viewed mapped' AS check_name, IFNULL((SELECT name = 'blog_viewed' AND type = 'view' AND env = 'production' AND user_id IS NULL AND anon_id = 'anon_22222222-2222-4222-8222-222222222222' AND platform = 0 AND country = 'IN' AND client_ts = ts AND JSON_VALUE(properties, '$.signed_in_flg') = 'false' AND JSON_VALUE(properties, '$.referrer') = '1' AND JSON_VALUE(properties, '$.has_quest_flg') = 'true' AND JSON_VALUE(properties, '$.signed_in') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e01'), FALSE) AS ok),
  STRUCT('e01 person_id is the user later seen on the device' AS check_name, IFNULL((SELECT person_id = 'user-c' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e01'), FALSE) AS ok),
  STRUCT('no $ key but $current_url and $pathname in events_clean_all' AS check_name, IFNULL((SELECT COUNT(*) FROM `onquest_analytics_g1_check.events_clean_all`, UNNEST(JSON_KEYS(properties, 1)) AS key WHERE STARTS_WITH(key, '$') AND key NOT IN ('$current_url', '$pathname')) = 0, FALSE) AS ok),
  STRUCT('no city, postcode, IP, lat/long or email anywhere in events_clean_all' AS check_name, IFNULL((SELECT COUNTIF(REGEXP_CONTAINS(TO_JSON_STRING(clean), r'Panaji|403001|203\.0\.113|15\.49|73\.82|c@example')) FROM `onquest_analytics_g1_check.events_clean_all` AS clean) = 0, FALSE) AS ok),
  STRUCT('events_people_all keeps user_info' AS check_name, IFNULL((SELECT JSON_VALUE(user_info, '$.email_id') = 'c@example.com' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e04'), FALSE) AS ok),
  STRUCT('e04 v2 row: client_ts, platform, $current_url kept, no user_info in properties' AS check_name, IFNULL((SELECT client_ts = TIMESTAMP '2026-11-27 10:00:00+00' AND platform = 1 AND person_id = 'user-c' AND JSON_VALUE(properties, '$."$current_url"') IS NOT NULL AND JSON_QUERY(properties, '$.user_info') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e04'), FALSE) AS ok),
  STRUCT('e03 v1 server blog_published: identity, values, anon_id from a later browser row' AS check_name, IFNULL((SELECT user_id = 'user-c' AND type = 'server' AND env = 'production' AND client_ts IS NULL AND anon_id = 'anon_22222222-2222-4222-8222-222222222222' AND JSON_VALUE(properties, '$.visibility') = '1' AND JSON_VALUE(properties, '$.photo_count') = '3' AND JSON_VALUE(properties, '$.has_quest_flg') = 'false' AND JSON_VALUE(properties, '$.has_place_flg') = 'true' AND JSON_VALUE(properties, '$.photos') IS NULL AND JSON_VALUE(properties, '$.server_ts') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e03'), FALSE) AS ok),
  STRUCT('e05 v1 create_option_tapped on a vercel.app URL is preview' AS check_name, IFNULL((SELECT name = 'create_option_click' AND type = 'click' AND env = 'preview' AND platform = 1 AND JSON_VALUE(properties, '$.option') = '1' AND JSON_VALUE(properties, '$.available_flg') = 'false' AND JSON_VALUE(properties, '$.available') IS NULL AND person_id = 'anon_33333333-3333-4333-8333-333333333333' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e05'), FALSE) AS ok),
  STRUCT('e06 $pageview: view, production, route template kept, other $ keys gone' AS check_name, IFNULL((SELECT type = 'view' AND env = 'production' AND JSON_VALUE(properties, '$."$pathname"') = '/home' AND JSON_VALUE(properties, '$."$screen_width"') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e06'), FALSE) AS ok),
  STRUCT('e11 user-b keeps signed-in rows on the deleted device' AS check_name, IFNULL((SELECT user_id = 'user-b' AND anon_id = 'anon_11111111-1111-4111-8111-111111111111' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e11'), FALSE) AS ok),
  STRUCT('e12 account_deleted kept, no anon_id' AS check_name, IFNULL((SELECT name = 'account_deleted' AND user_id = 'user-a' AND anon_id IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e12'), FALSE) AS ok),
  STRUCT('e13 blog_managed visibility' AS check_name, IFNULL((SELECT name = 'visibility_changed' AND JSON_VALUE(properties, '$.content_type') = '1' AND JSON_VALUE(properties, '$.content_id') = 'b1' AND JSON_VALUE(properties, '$.to_visibility') = '2' AND JSON_VALUE(properties, '$.action') IS NULL AND JSON_VALUE(properties, '$.blog_id') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e13'), FALSE) AS ok),
  STRUCT('e14 blog_managed comments' AS check_name, IFNULL((SELECT name = 'comments_toggled' AND JSON_VALUE(properties, '$.comments_on_flg') = 'false' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e14'), FALSE) AS ok),
  STRUCT('e15 blog_managed delete' AS check_name, IFNULL((SELECT name = 'content_deleted' AND JSON_VALUE(properties, '$.was_published_flg') = 'true' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e15'), FALSE) AS ok),
  STRUCT('e16 blog_managed edit' AS check_name, IFNULL((SELECT name = 'blog_updated' AND JSON_VALUE(properties, '$.blog_id') = 'b1' AND JSON_VALUE(properties, '$.action') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e16'), FALSE) AS ok),
  STRUCT('e17 blog_deleted' AS check_name, IFNULL((SELECT name = 'content_deleted' AND JSON_VALUE(properties, '$.was_published_flg') = 'false' AND JSON_VALUE(properties, '$.photo_count') = '2' AND JSON_VALUE(properties, '$.status') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e17'), FALSE) AS ok),
  STRUCT('e18 blog_liked' AS check_name, IFNULL((SELECT name = 'content_liked' AND JSON_VALUE(properties, '$.content_id') = 'b1' AND JSON_VALUE(properties, '$.unlike_flg') = 'true' AND JSON_VALUE(properties, '$.source') = '3' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e18'), FALSE) AS ok),
  STRUCT('e19 blog_comment_posted' AS check_name, IFNULL((SELECT name = 'comment_posted' AND JSON_VALUE(properties, '$.comment_length') = '42' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e19'), FALSE) AS ok),
  STRUCT('e20 legal_page_viewed values' AS check_name, IFNULL((SELECT name = 'legal_page_viewed' AND JSON_VALUE(properties, '$.page') = '1' AND JSON_VALUE(properties, '$.source') = '1' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e20'), FALSE) AS ok),
  STRUCT('e21 blog_create_started source' AS check_name, IFNULL((SELECT type = 'view' AND JSON_VALUE(properties, '$.click_loc') = '1' AND JSON_VALUE(properties, '$.source') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e21'), FALSE) AS ok),
  STRUCT('e22 blog_quest_linked' AS check_name, IFNULL((SELECT name = 'blog_editor_action' AND JSON_VALUE(properties, '$.action') = '7' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e22'), FALSE) AS ok),
  STRUCT('e23 blog_previewed' AS check_name, IFNULL((SELECT name = 'blog_editor_action' AND JSON_VALUE(properties, '$.action') = '5' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e23'), FALSE) AS ok),
  STRUCT('e24 blog_draft_saved' AS check_name, IFNULL((SELECT JSON_VALUE(properties, '$.photo_count') = '4' AND JSON_VALUE(properties, '$.photos') IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e24'), FALSE) AS ok),
  STRUCT('e25 blog_quest_opened' AS check_name, IFNULL((SELECT name = 'blog_quest_click' AND JSON_VALUE(properties, '$.view_id') = 'v1' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e25'), FALSE) AS ok),
  STRUCT('e26 blog_read_end unchanged' AS check_name, IFNULL((SELECT name = 'blog_read_end' AND type = 'client' AND JSON_VALUE(properties, '$.seconds') = '30' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e26'), FALSE) AS ok),
  STRUCT('e28 preview sign-up: anon_id filled, first_seen_ts derived' AS check_name, IFNULL((SELECT env = 'preview' AND anon_id = 'anon_44444444-4444-4444-8444-444444444444' AND TIMESTAMP(JSON_VALUE(properties, '$.first_seen_ts')) = TIMESTAMP '2026-11-26 08:00:00+00' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e28'), FALSE) AS ok),
  STRUCT('e30 days_since_last_sign_in derived' AS check_name, IFNULL((SELECT JSON_VALUE(properties, '$.days_since_last_sign_in') = '2' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e30'), FALSE) AS ok),
  STRUCT('e31 notification_sent never gets an anon_id' AS check_name, IFNULL((SELECT anon_id IS NULL FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e31'), FALSE) AS ok),
  STRUCT('e32 no env, site_url on vercel.app is preview' AS check_name, IFNULL((SELECT env = 'preview' FROM `onquest_analytics_g1_check.events_people_all` WHERE event_id = 'e32'), FALSE) AS ok),
  STRUCT('events_clean_all has the same rows' AS check_name, IFNULL((SELECT COUNT(*) FROM `onquest_analytics_g1_check.events_clean_all`) = 27, FALSE) AS ok)
]);

-- Expect no rows here.
SELECT check_name AS failing_check FROM fixture_checks WHERE NOT ok;

ASSERT NOT EXISTS (SELECT 1 FROM fixture_checks WHERE NOT ok)
  AS 'G1 fixture check failed: see the failing_check list above. Drop onquest_analytics_g1_check by hand.';

DROP SCHEMA `onquest_analytics_g1_check` CASCADE;

-- =============================================================================================
-- PART B: apply. Paste from here to the end and Run (a separate run from Part A).
-- =============================================================================================
-- ==== deleted_users.sql ====
-- deleted_users: the user key of every deleted account, and nothing else about the person.
-- Written by the analytics erasure job (AN-04, docs/specs/analytics-v2.md §5.2) on its first run
-- for a key. events_people_all anti-joins it, so a row that reaches BigQuery after the 30-day
-- re-runs is still never read (except account_deleted, kept so deletions can be counted).
CREATE TABLE IF NOT EXISTS `onquest_analytics.deleted_users` (
  user_id STRING NOT NULL OPTIONS (description = 'User key of a deleted account'),
  deleted_at TIMESTAMP NOT NULL OPTIONS (description = 'When analytics erasure first ran for this key')
)
OPTIONS (description = 'Key-only list of deleted accounts (analytics-v2 spec 5.2). No personal data.');

-- ==== deleted_devices.sql ====
-- deleted_devices: the anon_ids (random device ids) seen with a deleted account's key. The erasure
-- job (AN-04) stores them on its first run, so the daily re-runs can still delete signed-out rows
-- from those devices that reach BigQuery late, after the rows linking them to the key are gone.
-- events_people_all anti-joins it with the shared-device guard: only signed-out rows or the
-- deleted person's own rows are hidden, never another person's signed-in rows.
CREATE TABLE IF NOT EXISTS `onquest_analytics.deleted_devices` (
  anon_id STRING NOT NULL OPTIONS (description = 'anon_<uuid> device id seen with the deleted key'),
  user_id STRING NOT NULL OPTIONS (description = 'User key of the deleted account'),
  deleted_at TIMESTAMP NOT NULL OPTIONS (description = 'When analytics erasure first stored this device')
)
OPTIONS (description = 'Device ids of deleted accounts (analytics-v2 spec 5.2). Random ids and keys only.');

-- ==== events_people_all.sql ====
-- events_people_all: every PostHog event in v2 terms, both environments, WITH user_info (email,
-- username, city). Founders only (decision 0004). Everyone else reads events_clean, which is this
-- view without user_info and filtered to env = 'production'. docs/specs/analytics-v2.md §5.3.
--
-- Reads the PostHog batch export `onquest_analytics.events`, whose `properties` column is JSON
-- (confirmed by the CTO at G1, 26 Nov 2026).
--
-- What it does, in order:
--   raw        $-events dropped except $pageview. Only uuid, event, distinct_id, timestamp,
--              properties and site_url are read: never ip, set, set_once, person_properties or
--              elements (raw IP and PostHog person/location data).
--   deduped    one row per event_id; is_bot_flg = true dropped.
--   renamed    v1 names → v2 names (the table in spec §5.3, same as lib/analytics/renameMap.ts).
--   rewritten  v1 property names and string values → v2. Each branch leaves a v2 row unchanged,
--              so rows sent after the cut-over with the same name pass through.
--   common     the common columns, and `properties` rebuilt from an allowlist: the v2 taxonomy
--              properties, the common properties and $current_url / $pathname (route templates
--              on $pageview). Every other key goes, so no $geoip_*, $set, $ip or lat/long ever
--              reaches a view; user_info is its own column. Rows without env (v1, and v2 before
--              AN-03) take it from the first of $current_url, $host, site_url whose host is ours:
--              onquest.in / www.onquest.in → production, *.vercel.app or localhost → preview;
--              none → production. Their user_id is a distinct_id that isn't anon_…, their anon_id
--              the anon_… distinct_id, their country $geoip_country_code.
--   kept       deleted people's rows left out (deleted_users, deleted_devices with the
--              shared-device guard), except account_deleted.
--   filled     server events' null anon_id filled from the same user's browser rows while the
--              oq_actx cookie is off: the latest at or before the event, else the earliest after.
--   (final)    person_id for DAU; first_seen_ts and days_since_last_sign_in derived (spec D7).
--
-- Environments: the anon_id fill, person_id and the derived properties are computed across both
-- environments before events_clean filters to production. That's safe only because Preview's
-- user keys and anon ids never match Production's (separate Supabase projects and origins, D15).
--
-- Time: ts is PostHog's `timestamp`. For v1 browser rows, and v2 browser rows sent before AN-03
-- (whose client still sent `timestamp`), that is the DEVICE clock, also copied to client_ts.
-- From AN-03 on, browser rows get the server time and client_ts is the device time.
CREATE OR REPLACE VIEW `onquest_analytics.events_people_all`
OPTIONS (
  description = 'Founders only: v2 events with user_info, all environments (analytics-v2 spec 5.3). ts is device time for browser rows sent without env and before AN-03 (cut-over: AN-02 deploy). Others read events_clean.'
)
AS
WITH
raw AS (
  SELECT
    uuid,
    event,
    distinct_id,
    `timestamp` AS exported_ts,
    properties AS props,
    site_url
  FROM `onquest_analytics.events`
  WHERE NOT STARTS_WITH(event, '$') OR event = '$pageview'
),

deduped AS (
  SELECT
    COALESCE(JSON_VALUE(props, '$.event_id'), uuid) AS event_id,
    event AS raw_name,
    distinct_id,
    exported_ts,
    props,
    site_url,
    JSON_VALUE(props, '$.env') AS raw_env
  FROM raw
  WHERE COALESCE(JSON_VALUE(props, '$.is_bot_flg'), 'false') != 'true'
  QUALIFY ROW_NUMBER() OVER (
    PARTITION BY COALESCE(JSON_VALUE(props, '$.event_id'), uuid) ORDER BY exported_ts, uuid
  ) = 1
),

renamed AS (
  SELECT
    *,
    CASE raw_name
      WHEN 'create_option_tapped' THEN 'create_option_click'
      WHEN 'blog_managed' THEN
        CASE JSON_VALUE(props, '$.action')
          WHEN 'visibility' THEN 'visibility_changed'
          WHEN 'comments' THEN 'comments_toggled'
          WHEN 'delete' THEN 'content_deleted'
          WHEN 'edit' THEN 'blog_updated'
          ELSE raw_name
        END
      WHEN 'blog_deleted' THEN 'content_deleted'
      WHEN 'blog_liked' THEN 'content_liked'
      WHEN 'blog_comment_posted' THEN 'comment_posted'
      WHEN 'blog_quest_linked' THEN 'blog_editor_action'
      WHEN 'blog_previewed' THEN 'blog_editor_action'
      WHEN 'blog_quest_opened' THEN 'blog_quest_click'
      ELSE raw_name
    END AS name
  FROM deduped
),

rewritten AS (
  SELECT
    event_id,
    raw_name,
    name,
    distinct_id,
    exported_ts,
    raw_env,
    site_url,
    CASE
      WHEN raw_name = 'create_option_tapped' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.option', CASE JSON_VALUE(props, '$.option') WHEN 'quest' THEN 0 WHEN 'blog' THEN 1 END,
            '$.available_flg', SAFE_CAST(JSON_VALUE(props, '$.available') AS BOOL)
          ),
          '$.available'
        )
      WHEN raw_name = 'blog_managed' AND JSON_VALUE(props, '$.action') = 'visibility' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.content_type', 1,
            '$.content_id', JSON_VALUE(props, '$.blog_id'),
            '$.to_visibility',
            CASE JSON_VALUE(props, '$.value') WHEN 'public' THEN 0 WHEN 'unlisted' THEN 1 WHEN 'private' THEN 2 END
          ),
          '$.blog_id', '$.action', '$.value'
        )
      WHEN raw_name = 'blog_managed' AND JSON_VALUE(props, '$.action') = 'comments' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.content_type', 1,
            '$.content_id', JSON_VALUE(props, '$.blog_id'),
            '$.comments_on_flg', CASE JSON_VALUE(props, '$.value') WHEN 'on' THEN TRUE WHEN 'off' THEN FALSE END
          ),
          '$.blog_id', '$.action', '$.value'
        )
      WHEN raw_name = 'blog_managed' AND JSON_VALUE(props, '$.action') = 'delete' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.content_type', 1,
            '$.content_id', JSON_VALUE(props, '$.blog_id'),
            '$.was_published_flg', TRUE
          ),
          '$.blog_id', '$.action', '$.value'
        )
      WHEN raw_name = 'blog_managed' AND JSON_VALUE(props, '$.action') = 'edit' THEN
        JSON_REMOVE(props, '$.action', '$.value')
      WHEN raw_name = 'blog_deleted' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.content_type', 1,
            '$.content_id', JSON_VALUE(props, '$.blog_id'),
            '$.was_published_flg', FALSE,
            '$.photo_count', SAFE_CAST(JSON_VALUE(props, '$.photos') AS INT64)
          ),
          '$.blog_id', '$.status', '$.photos', '$.chars_bucket', '$.has_quest'
        )
      WHEN raw_name = 'blog_liked' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.content_type', 1,
            '$.content_id', JSON_VALUE(props, '$.blog_id'),
            '$.unlike_flg', SAFE_CAST(JSON_VALUE(props, '$.unlike') AS BOOL),
            '$.source',
            CASE JSON_VALUE(props, '$.source') WHEN 'blog_page' THEN 0 WHEN 'feed' THEN 2 WHEN 'after_sign_in' THEN 3 END
          ),
          '$.blog_id', '$.unlike'
        )
      WHEN raw_name = 'blog_comment_posted' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.content_type', 1,
            '$.content_id', JSON_VALUE(props, '$.blog_id'),
            '$.comment_length', SAFE_CAST(JSON_VALUE(props, '$.length') AS INT64)
          ),
          '$.blog_id', '$.length'
        )
      WHEN raw_name = 'legal_page_viewed' THEN
        JSON_SET(
          props,
          '$.page',
          CASE JSON_VALUE(props, '$.page')
            WHEN 'privacy' THEN 0
            WHEN 'terms' THEN 1
            ELSE SAFE_CAST(JSON_VALUE(props, '$.page') AS INT64)
          END,
          '$.source',
          CASE JSON_VALUE(props, '$.source')
            WHEN 'sign_in' THEN 0
            WHEN 'settings' THEN 1
            WHEN 'footer' THEN 2
            WHEN 'direct' THEN 3
            ELSE SAFE_CAST(JSON_VALUE(props, '$.source') AS INT64)
          END
        )
      WHEN raw_name = 'blog_create_started' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.click_loc',
            COALESCE(
              SAFE_CAST(JSON_VALUE(props, '$.click_loc') AS INT64),
              CASE JSON_VALUE(props, '$.source') WHEN 'create' THEN 0 WHEN 'write_your_own' THEN 1 END
            )
          ),
          '$.source'
        )
      WHEN raw_name = 'blog_quest_linked' THEN
        JSON_SET(props, '$.action', CASE JSON_VALUE(props, '$.action') WHEN 'link' THEN 3 WHEN 'remove' THEN 7 END)
      WHEN raw_name = 'blog_previewed' THEN
        JSON_SET(props, '$.action', 5)
      WHEN raw_name = 'blog_draft_saved' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.photo_count',
            COALESCE(
              SAFE_CAST(JSON_VALUE(props, '$.photo_count') AS INT64),
              SAFE_CAST(JSON_VALUE(props, '$.photos') AS INT64)
            )
          ),
          '$.photos'
        )
      WHEN raw_name = 'blog_published' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.visibility',
            CASE JSON_VALUE(props, '$.visibility')
              WHEN 'public' THEN 0
              WHEN 'unlisted' THEN 1
              WHEN 'private' THEN 2
              ELSE SAFE_CAST(JSON_VALUE(props, '$.visibility') AS INT64)
            END,
            '$.photo_count',
            COALESCE(
              SAFE_CAST(JSON_VALUE(props, '$.photo_count') AS INT64),
              SAFE_CAST(JSON_VALUE(props, '$.photos') AS INT64)
            ),
            '$.has_quest_flg',
            COALESCE(
              SAFE_CAST(JSON_VALUE(props, '$.has_quest_flg') AS BOOL),
              SAFE_CAST(JSON_VALUE(props, '$.has_quest') AS BOOL)
            ),
            '$.has_place_flg',
            COALESCE(
              SAFE_CAST(JSON_VALUE(props, '$.has_place_flg') AS BOOL),
              SAFE_CAST(JSON_VALUE(props, '$.has_place') AS BOOL)
            )
          ),
          '$.photos', '$.has_quest', '$.has_place'
        )
      WHEN raw_name = 'blog_viewed' THEN
        JSON_REMOVE(
          JSON_SET(
            props,
            '$.signed_in_flg',
            COALESCE(
              SAFE_CAST(JSON_VALUE(props, '$.signed_in_flg') AS BOOL),
              SAFE_CAST(JSON_VALUE(props, '$.signed_in') AS BOOL)
            ),
            '$.referrer',
            CASE JSON_VALUE(props, '$.referrer')
              WHEN 'none' THEN 0
              WHEN 'whatsapp' THEN 1
              WHEN 'instagram' THEN 2
              WHEN 'other' THEN 3
              ELSE SAFE_CAST(JSON_VALUE(props, '$.referrer') AS INT64)
            END,
            '$.has_quest_flg',
            COALESCE(
              SAFE_CAST(JSON_VALUE(props, '$.has_quest_flg') AS BOOL),
              SAFE_CAST(JSON_VALUE(props, '$.has_quest') AS BOOL)
            )
          ),
          '$.signed_in', '$.has_quest'
        )
      ELSE props
    END AS props
  FROM renamed
),

common AS (
  SELECT
    event_id,
    name,
    COALESCE(
      JSON_VALUE(props, '$.type'),
      -- The v2 type of each event (taxonomyV2.ts; metricsSql.test.ts checks these lists).
      CASE
        WHEN name IN (
          'account_delete_click', 'blog_editor_action', 'blog_format_click',
          'blog_quest_click', 'comment_box_open', 'create_option_click', 'create_quest_click',
          'draft_resumed', 'feed_load_more_click', 'feedback_click', 'instagram_export',
          'manage_menu_open', 'notification_click', 'photos_selected', 'preview_exit',
          'profile_tab_click', 'quest_edit', 'quest_fullscreen', 'quest_page_turn',
          'quest_photo_click', 'report_click', 'search', 'search_result_click', 'share_click',
          'sign_in_click', 'tab_click', 'template_select', 'welcome_click',
          'whats_a_quest_click'
        ) THEN 'click'
        WHEN name IN (
          'app_opened', 'blog_create_started', 'blog_unavailable', 'blog_viewed',
          'error_shown', 'explore_viewed', 'follow_list_viewed', 'guide_viewed', 'home_viewed',
          'legal_page_viewed', 'photo_limit_hit', 'profile_viewed', 'quest_preview',
          'quest_unavailable', 'quest_viewed', 'settings_viewed', 'username_rejected',
          'welcome_step_viewed'
        ) THEN 'view'
        WHEN name IN (
          'blog_read_end', 'quest_create_abandoned', 'quest_view_ended'
        ) THEN 'client'
        WHEN name IN (
          'account_deleted', 'blog_draft_saved', 'blog_published', 'blog_updated',
          'comment_deleted', 'comment_posted', 'comments_toggled', 'content_deleted',
          'content_liked', 'notification_sent', 'profile_updated', 'quest_arranged',
          'quest_creation_complete', 'quest_draft_created', 'quest_updated', 'setting_changed',
          'user_followed', 'user_signed_in', 'user_signed_out', 'user_signed_up',
          'username_set', 'visibility_changed'
        ) THEN 'server'
        -- Page views count as views for DAU (Metrics "Daily / weekly active users").
        WHEN name = '$pageview' THEN 'view'
      END
    ) AS type,
    COALESCE(
      raw_env,
      (
        SELECT IF(host IN ('onquest.in', 'www.onquest.in'), 'production', 'preview')
        FROM UNNEST([
          LOWER(NET.HOST(JSON_VALUE(props, '$."$current_url"'))),
          LOWER(NET.HOST(JSON_VALUE(props, '$."$host"'))),
          LOWER(NET.HOST(site_url))
        ]) AS host WITH OFFSET AS position
        -- Only our own hosts decide; anything else (e.g. PostHog's own URL) is ignored.
        WHERE host IN ('onquest.in', 'www.onquest.in', 'localhost', '127.0.0.1') OR ENDS_WITH(host, '.vercel.app')
        ORDER BY position
        LIMIT 1
      ),
      'production'
    ) AS env,
    exported_ts AS ts,
    raw_env,
    exported_ts,
    COALESCE(
      JSON_VALUE(props, '$.user_id'),
      IF(raw_env IS NULL AND NOT STARTS_WITH(distinct_id, 'anon_'), distinct_id, NULL)
    ) AS user_id,
    COALESCE(
      JSON_VALUE(props, '$.anon_id'),
      IF(raw_env IS NULL AND STARTS_WITH(distinct_id, 'anon_'), distinct_id, NULL)
    ) AS anon_id,
    JSON_VALUE(props, '$.session_id') AS session_id,
    CASE JSON_VALUE(props, '$.platform')
      WHEN 'web_mobile' THEN 0
      WHEN 'web_desktop' THEN 1
      ELSE SAFE_CAST(JSON_VALUE(props, '$.platform') AS INT64)
    END AS platform,
    JSON_VALUE(props, '$.os') AS os,
    JSON_VALUE(props, '$.browser') AS browser,
    JSON_VALUE(props, '$.screen') AS screen,
    COALESCE(
      JSON_VALUE(props, '$.country'),
      -- v1 browser rows: PostHog GeoIP, country only (nothing finer is ever read).
      IF(raw_env IS NULL, JSON_VALUE(props, '$."$geoip_country_code"'), NULL)
    ) AS country,
    JSON_VALUE(props, '$.app_version') AS app_version,
    SAFE.TIMESTAMP(JSON_VALUE(props, '$.client_ts')) AS sent_client_ts,
    JSON_QUERY(props, '$.user_info') AS user_info,
    -- Allowlist (metricsSql.test.ts checks it equals the taxonomy's keys). allowlist:start
    JSON_STRIP_NULLS(
